import {
  EDITOR_ONLY_SHELL_MODE,
  FULL_EDITOR_SHELL_MODE,
} from './page-config.ts';

const defaultPluginRuntime = {
  keyboardSpecifications: new Map(),
  listeners: new Set(),
  nextPluginId: 1,
  openLyricSpecifications: new Map(),
  registeredPlugins: new Set(),
  spellcheckSpecifications: new Map(),
  transcriptSpecifications: new Map(),
};

const runtimeHost = globalThis as typeof globalThis & {
  __openLyricEditorPluginRuntime?: typeof defaultPluginRuntime;
};

const pluginRuntime =
  runtimeHost.__openLyricEditorPluginRuntime ||
  (runtimeHost.__openLyricEditorPluginRuntime = defaultPluginRuntime);

function normalizePluginExampleIdPart(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizePluginLanguageCode(languageCode) {
  const normalizedValue = String(languageCode || '')
    .trim()
    .toLowerCase();

  return normalizedValue || null;
}

function looksLikeCssText(value) {
  return value.startsWith('@') || /[\r\n{;]/.test(value);
}

function normalizePluginStyleEntries(styleValue) {
  if (styleValue == null) {
    return [];
  }

  const styleEntries = Array.isArray(styleValue) ? styleValue : [styleValue];

  return styleEntries.flatMap((styleEntry) => {
    if (!styleEntry) {
      return [];
    }

    if (typeof styleEntry === 'string') {
      const trimmedValue = styleEntry.trim();
      if (!trimmedValue) {
        return [];
      }

      return looksLikeCssText(trimmedValue)
        ? [{ cssText: styleEntry }]
        : [{ href: trimmedValue }];
    }

    if (typeof styleEntry !== 'object') {
      return [];
    }

    const href =
      typeof styleEntry.href === 'string' && styleEntry.href.trim()
        ? styleEntry.href.trim()
        : '';
    const cssText =
      typeof styleEntry.cssText === 'string' && styleEntry.cssText.trim()
        ? styleEntry.cssText
        : '';

    if (href) {
      return [
        {
          href,
          media:
            typeof styleEntry.media === 'string' && styleEntry.media.trim()
              ? styleEntry.media.trim()
              : '',
        },
      ];
    }

    if (cssText) {
      return [
        {
          cssText,
          media:
            typeof styleEntry.media === 'string' && styleEntry.media.trim()
              ? styleEntry.media.trim()
              : '',
        },
      ];
    }

    return [];
  });
}

function normalizePluginAliases(languageCode, aliases) {
  return Array.from(
    new Set(
      [languageCode]
        .concat(Array.isArray(aliases) ? aliases : [])
        .map(normalizePluginLanguageCode)
        .filter(Boolean),
    ),
  );
}

const KNOWN_EDITOR_SHELL_MODES = new Set([
  EDITOR_ONLY_SHELL_MODE,
  FULL_EDITOR_SHELL_MODE,
]);

function normalizePluginEditorShellModes(shellModesValue) {
  if (shellModesValue == null) {
    return [];
  }

  const shellModes = Array.isArray(shellModesValue)
    ? shellModesValue
    : [shellModesValue];

  return Array.from(
    new Set(
      shellModes
        .map((shellMode) =>
          String(shellMode ?? '')
            .trim()
            .toLowerCase(),
        )
        .filter((shellMode) => KNOWN_EDITOR_SHELL_MODES.has(shellMode)),
    ),
  );
}

function normalizeSpellcheckSpecification(specification) {
  if (!specification || typeof specification !== 'object') {
    throw new TypeError('Plugin spellChecker must be an object.');
  }

  const languageCode = normalizePluginLanguageCode(specification.languageCode);
  if (!languageCode) {
    throw new Error('Plugin spellChecker.languageCode is required.');
  }

  return {
    ...specification,
    actionLabel:
      typeof specification.actionLabel === 'string' &&
      specification.actionLabel.trim()
        ? specification.actionLabel.trim()
        : '',
    aliases: normalizePluginAliases(languageCode, specification.aliases),
    defaultEnabled: Boolean(specification.defaultEnabled),
    dictionaryName:
      typeof specification.dictionaryName === 'string' &&
      specification.dictionaryName.trim()
        ? specification.dictionaryName.trim()
        : languageCode,
    displayName:
      typeof specification.displayName === 'string' &&
      specification.displayName.trim()
        ? specification.displayName.trim()
        : languageCode.toUpperCase(),
    languageCode,
  };
}

function normalizeSpellcheckEntries(spellCheckerValue) {
  if (spellCheckerValue == null) {
    return [];
  }

  const spellCheckerEntries = Array.isArray(spellCheckerValue)
    ? spellCheckerValue
    : [spellCheckerValue];

  return spellCheckerEntries.map(normalizeSpellcheckSpecification);
}

function normalizeKeyboardSpecification(specification) {
  if (!specification || typeof specification !== 'object') {
    throw new TypeError('Plugin keyboard must be an object.');
  }

  const keyboardId = normalizePluginLanguageCode(specification.id);
  if (!keyboardId) {
    throw new Error('Plugin keyboard.id is required.');
  }

  const create =
    typeof specification.create === 'function'
      ? specification.create
      : typeof specification.mount === 'function'
        ? specification.mount
        : null;

  if (!create) {
    throw new Error('Plugin keyboard.create is required.');
  }

  return {
    ...specification,
    create,
    id: keyboardId,
  };
}

function normalizeKeyboardEntries(keyboardValue) {
  if (keyboardValue == null) {
    return [];
  }

  const keyboardEntries = Array.isArray(keyboardValue)
    ? keyboardValue
    : [keyboardValue];

  return keyboardEntries.map(normalizeKeyboardSpecification);
}

function normalizeTranscriptSpecification(specification) {
  if (!specification || typeof specification !== 'object') {
    throw new TypeError('Plugin transcript must be an object.');
  }

  const transcriptId = normalizePluginLanguageCode(specification.id);
  if (!transcriptId) {
    throw new Error('Plugin transcript.id is required.');
  }

  const create =
    typeof specification.create === 'function'
      ? specification.create
      : typeof specification.mount === 'function'
        ? specification.mount
        : null;

  if (!create) {
    throw new Error('Plugin transcript.create is required.');
  }

  return {
    ...specification,
    actionLabel:
      typeof specification.actionLabel === 'string' &&
      specification.actionLabel.trim()
        ? specification.actionLabel.trim()
        : '',
    create,
    displayName:
      typeof specification.displayName === 'string' &&
      specification.displayName.trim()
        ? specification.displayName.trim()
        : transcriptId,
    id: transcriptId,
  };
}

function normalizeTranscriptEntries(transcriptValue) {
  if (transcriptValue == null) {
    return [];
  }

  const transcriptEntries = Array.isArray(transcriptValue)
    ? transcriptValue
    : [transcriptValue];

  return transcriptEntries.map(normalizeTranscriptSpecification);
}

function normalizeOpenLyricSection(sectionValue, label) {
  if (sectionValue == null) {
    return null;
  }

  if (
    !sectionValue ||
    typeof sectionValue !== 'object' ||
    Array.isArray(sectionValue)
  ) {
    throw new TypeError(`Plugin openLyric.${label} must be an object.`);
  }

  return {
    ...sectionValue,
  };
}

function normalizeOpenLyricSpecification(specification, pluginId) {
  if (specification == null) {
    return null;
  }

  if (
    !specification ||
    typeof specification !== 'object' ||
    Array.isArray(specification)
  ) {
    throw new TypeError('Plugin openLyric must be an object.');
  }

  const openLyricId =
    typeof specification.id === 'string' && specification.id.trim()
      ? specification.id.trim()
      : pluginId;

  return {
    ...specification,
    document: normalizeOpenLyricSection(specification.document, 'document'),
    domain: normalizeOpenLyricSection(specification.domain, 'domain'),
    export: normalizeOpenLyricSection(specification.export, 'export'),
    id: openLyricId,
    monaco: normalizeOpenLyricSection(specification.monaco, 'monaco'),
    preview: normalizeOpenLyricSection(specification.preview, 'preview'),
  };
}

function resolvePluginExampleGroupTitle(pluginData, specification) {
  const specificationGroupTitle =
    typeof specification?.groupTitle === 'string' &&
    specification.groupTitle.trim()
      ? specification.groupTitle.trim()
      : '';

  if (specificationGroupTitle) {
    return specificationGroupTitle;
  }

  const pluginGroupTitle =
    typeof pluginData?.exampleGroupTitle === 'string' &&
    pluginData.exampleGroupTitle.trim()
      ? pluginData.exampleGroupTitle.trim()
      : '';

  if (pluginGroupTitle) {
    return pluginGroupTitle;
  }

  const spellCheckerEntries = Array.isArray(pluginData?.spellChecker)
    ? pluginData.spellChecker
    : pluginData?.spellChecker
      ? [pluginData.spellChecker]
      : [];
  const spellCheckerDisplayName = spellCheckerEntries
    .map((entry) => {
      return typeof entry?.displayName === 'string'
        ? entry.displayName.trim()
        : '';
    })
    .find(Boolean);

  if (spellCheckerDisplayName) {
    return `${spellCheckerDisplayName} .md Examples`;
  }

  return 'Plugin .md Examples';
}

function resolvePluginExampleEditorShellModes(pluginData, specification) {
  const requestedShellModes =
    specification?.editorShellModes != null
      ? specification.editorShellModes
      : pluginData?.exampleEditorShellModes;

  return normalizePluginEditorShellModes(requestedShellModes);
}

function normalizePluginExampleSpecification(
  specification,
  pluginData,
  pluginId,
  index,
) {
  if (!specification || typeof specification !== 'object') {
    throw new TypeError('Plugin examples must be objects.');
  }

  const content =
    typeof specification.content === 'string' ? specification.content : '';

  if (!content.trim()) {
    throw new Error('Plugin example content is required.');
  }

  const requestedFileName =
    typeof specification.fileName === 'string' && specification.fileName.trim()
      ? specification.fileName.trim()
      : '';
  const requestedTitle =
    typeof specification.title === 'string' && specification.title.trim()
      ? specification.title.trim()
      : '';
  const requestedId =
    typeof specification.id === 'string' && specification.id.trim()
      ? specification.id.trim()
      : '';
  const idSource = requestedId || requestedFileName || requestedTitle;
  const normalizedIdPart = normalizePluginExampleIdPart(idSource);
  const generatedIdPart = normalizedIdPart || `example-${index + 1}`;
  const fileNameBase = requestedFileName || `${generatedIdPart}.md`;
  const fileName = /\.(md|markdown)$/iu.test(fileNameBase)
    ? fileNameBase
    : `${fileNameBase}.md`;

  return {
    content,
    description:
      typeof specification.description === 'string' &&
      specification.description.trim()
        ? specification.description.trim()
        : '',
    editorShellModes: resolvePluginExampleEditorShellModes(
      pluginData,
      specification,
    ),
    fileName,
    groupTitle: resolvePluginExampleGroupTitle(pluginData, specification),
    id: `${pluginId}:${generatedIdPart}`,
    pluginId,
    title: requestedTitle || fileName,
  };
}

function normalizePluginExampleEntries(exampleValue, pluginData, pluginId) {
  if (exampleValue == null) {
    return [];
  }

  const exampleEntries = Array.isArray(exampleValue)
    ? exampleValue
    : [exampleValue];
  const seenIds = new Set();

  return exampleEntries.flatMap((exampleEntry, index) => {
    const normalizedExample = normalizePluginExampleSpecification(
      exampleEntry,
      pluginData,
      pluginId,
      index,
    );

    if (seenIds.has(normalizedExample.id)) {
      throw new Error(
        `Plugin example "${normalizedExample.id}" is already registered.`,
      );
    }

    seenIds.add(normalizedExample.id);
    return normalizedExample;
  });
}

function normalizePluginPptxStyle(pptxStyleValue) {
  if (pptxStyleValue == null) {
    return null;
  }

  if (typeof pptxStyleValue !== 'object') {
    throw new TypeError('Plugin pptxStyle must be an object.');
  }

  const rawFontFamilyChoices = Array.isArray(pptxStyleValue.fontFamilyChoices)
    ? pptxStyleValue.fontFamilyChoices
    : pptxStyleValue.fontFamilyChoices == null
      ? []
      : [pptxStyleValue.fontFamilyChoices];
  const fontFamilyChoices = rawFontFamilyChoices
    .map((fontFamily) => String(fontFamily || '').trim())
    .filter(Boolean);
  const fontDetectionSampleText =
    typeof pptxStyleValue.fontDetectionSampleText === 'string' &&
    pptxStyleValue.fontDetectionSampleText.trim()
      ? pptxStyleValue.fontDetectionSampleText
      : '';
  const normalizedFontSize = Number(pptxStyleValue.fontSize);
  const fontSize =
    Number.isFinite(normalizedFontSize) && normalizedFontSize > 0
      ? normalizedFontSize
      : null;

  if (!fontFamilyChoices.length && !fontDetectionSampleText && !fontSize) {
    return null;
  }

  return {
    fontFamilyChoices,
    fontDetectionSampleText,
    fontSize,
  };
}

function installStyleEntry(styleEntry, pluginId, index) {
  if (!document.head) {
    throw new Error(
      'Document head is not available for plugin style injection.',
    );
  }

  let node;

  if (styleEntry.href) {
    node = document.createElement('link');
    node.rel = 'stylesheet';
    node.href = styleEntry.href;
  } else {
    node = document.createElement('style');
    node.textContent = styleEntry.cssText;
  }

  if (styleEntry.media) {
    node.media = styleEntry.media;
  }

  node.dataset.openLyricPluginId = pluginId;
  node.dataset.openLyricPluginStyleIndex = String(index);
  document.head.append(node);

  return {
    node,
  };
}

function notifyPluginListeners(event) {
  pluginRuntime.listeners.forEach((listener) => {
    try {
      listener(event);
    } catch (error) {
      console.error('Open Lyric plugin listener failed.', error);
    }
  });
}

function createPluginRegistration(
  pluginData,
  pptxStyle,
  openLyricSpecification,
  spellcheckSpecifications,
  keyboardSpecifications,
  transcriptSpecifications,
  draftExamples,
) {
  const requestedPluginId =
    typeof pluginData?.id === 'string' && pluginData.id.trim()
      ? pluginData.id.trim()
      : '';

  const pluginId =
    requestedPluginId || `ol-editor-plugin-${pluginRuntime.nextPluginId}`;
  pluginRuntime.nextPluginId += 1;

  return {
    draftExamples,
    disposed: false,
    id: pluginId,
    keyboardIds: keyboardSpecifications.map(({ id }) => id),
    openLyricIds: openLyricSpecification ? [openLyricSpecification.id] : [],
    openLyricSpecification,
    pluginData,
    pptxStyle,
    spellcheckLanguageCodes: spellcheckSpecifications.map(
      ({ languageCode }) => languageCode,
    ),
    styleEntries: [],
    transcriptIds: transcriptSpecifications.map(({ id }) => id),
  };
}

function registerPlugin(pluginData) {
  const normalizedPluginData =
    pluginData && typeof pluginData === 'object' ? pluginData : {};
  const requestedPluginId =
    typeof normalizedPluginData.id === 'string' &&
    normalizedPluginData.id.trim()
      ? normalizedPluginData.id.trim()
      : '';
  const pluginId =
    requestedPluginId || `ol-editor-plugin-${pluginRuntime.nextPluginId}`;
  const normalizedPptxStyle = normalizePluginPptxStyle(
    normalizedPluginData.pptxStyle,
  );
  const openLyricSpecification = normalizeOpenLyricSpecification(
    normalizedPluginData.openLyric,
    pluginId,
  );
  const spellcheckSpecifications = normalizeSpellcheckEntries(
    normalizedPluginData.spellChecker,
  );
  const keyboardSpecifications = normalizeKeyboardEntries(
    normalizedPluginData.keyboard,
  );
  const transcriptSpecifications = normalizeTranscriptEntries(
    normalizedPluginData.transcript,
  );
  const draftExamples = normalizePluginExampleEntries(
    normalizedPluginData.examples,
    normalizedPluginData,
    pluginId,
  );

  spellcheckSpecifications.forEach((specification) => {
    if (specification.languageCode === 'en') {
      throw new Error(
        'English spellcheck is built in and cannot be overridden by a plugin.',
      );
    }

    if (
      pluginRuntime.spellcheckSpecifications.has(specification.languageCode)
    ) {
      throw new Error(
        `Spellcheck language "${specification.languageCode}" is already registered.`,
      );
    }
  });

  keyboardSpecifications.forEach((specification) => {
    if (pluginRuntime.keyboardSpecifications.has(specification.id)) {
      throw new Error(
        `Keyboard plugin "${specification.id}" is already registered.`,
      );
    }
  });

  if (transcriptSpecifications.length > 1) {
    throw new Error('Only one transcript plugin can be registered at a time.');
  }

  transcriptSpecifications.forEach((specification) => {
    if (pluginRuntime.transcriptSpecifications.size > 0) {
      throw new Error(
        'Only one transcript plugin can be registered at a time.',
      );
    }

    if (pluginRuntime.transcriptSpecifications.has(specification.id)) {
      throw new Error(
        `Transcript plugin "${specification.id}" is already registered.`,
      );
    }
  });

  if (openLyricSpecification) {
    if (pluginRuntime.openLyricSpecifications.size > 0) {
      throw new Error(
        'Only one Open Lyric plugin can be registered at a time.',
      );
    }

    if (pluginRuntime.openLyricSpecifications.has(openLyricSpecification.id)) {
      throw new Error(
        `Open Lyric plugin "${openLyricSpecification.id}" is already registered.`,
      );
    }
  }

  const registeredData = createPluginRegistration(
    normalizedPluginData,
    normalizedPptxStyle,
    openLyricSpecification,
    spellcheckSpecifications,
    keyboardSpecifications,
    transcriptSpecifications,
    draftExamples,
  );
  const styleEntries = normalizePluginStyleEntries(normalizedPluginData.style);

  registeredData.styleEntries = styleEntries.map((styleEntry, index) => ({
    ...styleEntry,
    styleIndex: index,
    ...installStyleEntry(styleEntry, registeredData.id, index),
  }));

  spellcheckSpecifications.forEach((specification) => {
    pluginRuntime.spellcheckSpecifications.set(
      specification.languageCode,
      specification,
    );
  });

  keyboardSpecifications.forEach((specification) => {
    pluginRuntime.keyboardSpecifications.set(specification.id, specification);
  });

  transcriptSpecifications.forEach((specification) => {
    pluginRuntime.transcriptSpecifications.set(specification.id, specification);
  });

  if (openLyricSpecification) {
    pluginRuntime.openLyricSpecifications.set(
      openLyricSpecification.id,
      openLyricSpecification,
    );
  }

  pluginRuntime.registeredPlugins.add(registeredData);

  notifyPluginListeners({
    keyboardIds: registeredData.keyboardIds.slice(),
    openLyricIds: registeredData.openLyricIds.slice(),
    registeredData,
    spellcheckLanguageCodes: registeredData.spellcheckLanguageCodes.slice(),
    transcriptIds: registeredData.transcriptIds.slice(),
    type: 'registered',
  });

  return registeredData;
}

function unregisterPlugin(registeredData) {
  if (
    !registeredData ||
    typeof registeredData !== 'object' ||
    registeredData.disposed
  ) {
    return false;
  }

  registeredData.disposed = true;
  pluginRuntime.registeredPlugins.delete(registeredData);

  registeredData.styleEntries?.forEach(({ node }) => {
    node?.remove();
  });

  registeredData.spellcheckLanguageCodes?.forEach((languageCode) => {
    pluginRuntime.spellcheckSpecifications.delete(languageCode);
  });
  registeredData.keyboardIds?.forEach((keyboardId) => {
    pluginRuntime.keyboardSpecifications.delete(keyboardId);
  });
  registeredData.transcriptIds?.forEach((transcriptId) => {
    pluginRuntime.transcriptSpecifications.delete(transcriptId);
  });
  registeredData.openLyricIds?.forEach((openLyricId) => {
    pluginRuntime.openLyricSpecifications.delete(openLyricId);
  });

  notifyPluginListeners({
    keyboardIds: registeredData.keyboardIds.slice(),
    openLyricIds: registeredData.openLyricIds.slice(),
    registeredData,
    spellcheckLanguageCodes: registeredData.spellcheckLanguageCodes.slice(),
    transcriptIds: registeredData.transcriptIds.slice(),
    type: 'unregistered',
  });

  return true;
}

function getRegisteredSpellcheckSpecification(languageCode) {
  const normalizedLanguageCode = normalizePluginLanguageCode(languageCode);
  return normalizedLanguageCode
    ? pluginRuntime.spellcheckSpecifications.get(normalizedLanguageCode) || null
    : null;
}

function getRegisteredSpellcheckSpecifications() {
  return Array.from(pluginRuntime.spellcheckSpecifications.values());
}

function getRegisteredKeyboardSpecifications() {
  return Array.from(pluginRuntime.keyboardSpecifications.values());
}

function getRegisteredTranscriptSpecifications() {
  return Array.from(pluginRuntime.transcriptSpecifications.values());
}

function getRegisteredOpenLyricSpecification() {
  return Array.from(pluginRuntime.openLyricSpecifications.values())[0] || null;
}

function getRegisteredOpenLyricSpecifications() {
  return Array.from(pluginRuntime.openLyricSpecifications.values());
}

function getRegisteredPluginStyles() {
  return Array.from(pluginRuntime.registeredPlugins)
    .flatMap((registeredPlugin) =>
      (registeredPlugin?.styleEntries || []).map((styleEntry) => ({
        cssText:
          typeof styleEntry?.cssText === 'string' ? styleEntry.cssText : '',
        href: typeof styleEntry?.href === 'string' ? styleEntry.href : '',
        media: typeof styleEntry?.media === 'string' ? styleEntry.media : '',
        pluginId: registeredPlugin.id,
        styleIndex: Number.isInteger(styleEntry?.styleIndex)
          ? styleEntry.styleIndex
          : 0,
      })),
    )
    .filter((styleEntry) => styleEntry.href || styleEntry.cssText);
}

function getRegisteredPluginDraftExamples() {
  return Array.from(pluginRuntime.registeredPlugins).flatMap(
    (registeredPlugin) => {
      return Array.isArray(registeredPlugin?.draftExamples)
        ? registeredPlugin.draftExamples.map((draftExample) => ({
            ...draftExample,
          }))
        : [];
    },
  );
}

function getRegisteredPowerPointStyles() {
  return Array.from(pluginRuntime.registeredPlugins)
    .map((registeredPlugin) => {
      if (!registeredPlugin?.pptxStyle) {
        return null;
      }

      return {
        ...registeredPlugin.pptxStyle,
        pluginId: registeredPlugin.id,
      };
    })
    .filter(Boolean);
}

function subscribeToPluginRegistry(listener) {
  if (typeof listener !== 'function') {
    return () => {};
  }

  pluginRuntime.listeners.add(listener);

  return () => {
    pluginRuntime.listeners.delete(listener);
  };
}

export {
  getRegisteredKeyboardSpecifications,
  getRegisteredOpenLyricSpecification,
  getRegisteredOpenLyricSpecifications,
  getRegisteredPluginDraftExamples,
  getRegisteredPluginStyles,
  getRegisteredPowerPointStyles,
  getRegisteredSpellcheckSpecification,
  getRegisteredSpellcheckSpecifications,
  getRegisteredTranscriptSpecifications,
  registerPlugin,
  subscribeToPluginRegistry,
  unregisterPlugin,
};
